/* Pixel Hangman - cohesive palette: #1a1a2e, #16213e, #0f3460, #e94560, #f5f5f5 */
:root {
  --bg-dark: #1a1a2e;
  --bg-mid: #16213e;
  --bg-light: #0f3460;
  --accent: #e94560;
  --text-light: #f5f5f5;
  --font-stack: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background: var(--bg-dark);
  color: var(--text-light);
  font-family: var(--font-stack);
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.game-container {
  background: var(--bg-mid);
  border: 4px solid var(--bg-light);
  border-radius: 12px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 0 var(--bg-light);
}

h1 {
  text-align: center;
  font-size: 28px;
  margin-bottom: 20px;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--bg-dark);
}

.game-board {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

canvas {
  background: var(--bg-dark);
  border: 4px solid var(--bg-light);
  border-radius: 4px;
  width: 100%;
  max-width: 200px;
  height: auto;
  image-rendering: pixelated;
}

.word-display {
  font-size: 28px;
  letter-spacing: 8px;
  text-align: center;
  min-height: 40px;
  font-weight: 700;
  word-break: break-word;
  color: var(--text-light);
}

.message {
  font-size: 18px;
  min-height: 28px;
  text-align: center;
  color: var(--accent);
  font-weight: 600;
}

.letter-buttons {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(44px, 1fr));
  gap: 8px;
  width: 100%;
}

.letter-buttons button {
  font-family: var(--font-stack);
  font-size: 18px;
  font-weight: 700;
  padding: 10px 0;
  background: var(--bg-light);
  color: var(--text-light);
  border: 3px solid var(--bg-dark);
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  min-height: 44px;
}

.letter-buttons button:hover:not(:disabled) {
  background: var(--accent);
  transform: translateY(-2px);
}

.letter-buttons button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.letter-buttons button:active:not(:disabled) {
  transform: translateY(2px);
}

.letter-buttons button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: var(--bg-mid);
  border-color: var(--bg-dark);
}

.new-game-btn {
  font-family: var(--font-stack);
  font-size: 20px;
  font-weight: 700;
  padding: 12px 32px;
  background: var(--accent);
  color: var(--text-light);
  border: 3px solid var(--bg-dark);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.new-game-btn:hover {
  background: #ff5c7a;
  transform: translateY(-2px);
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--text-light);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: translateY(2px);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 24px;
  }
  .word-display {
    font-size: 22px;
    letter-spacing: 5px;
  }
  .letter-buttons {
    grid-template-columns: repeat(auto-fill, minmax(38px, 1fr));
  }
  .letter-buttons button {
    font-size: 16px;
    min-height: 38px;
  }
}

(function() {
  'use strict';

  const WORDS = ['JAVASCRIPT', 'PIXEL', 'HANGMAN', 'BROWSER', 'CANVAS', 'GAMING', 'KEYBOARD', 'ACCESSIBLE', 'RESPONSIVE', 'OFFLINE'];
  const MAX_WRONG = 6;

  const canvas = document.getElementById('hangman-canvas');
  const ctx = canvas.getContext('2d');
  const wordDisplay = document.getElementById('word-display');
  const messageEl = document.getElementById('message');
  const letterButtons = document.getElementById('letter-buttons');
  const newGameBtn = document.getElementById('new-game');

  let secretWord = '';
  let guessedLetters = new Set();
  let wrongGuesses = 0;
  let gameOver = false;

  function pickWord() {
    return WORDS[Math.floor(Math.random() * WORDS.length)];
  }

  function renderWord() {
    const display = secretWord.split('').map(function(ch) {
      return guessedLetters.has(ch) ? ch : '_';
    }).join(' ');
    wordDisplay.textContent = display;
  }

  function renderMessage() {
    if (gameOver) {
      const won = secretWord.split('').every(function(ch) { return guessedLetters.has(ch); });
      messageEl.textContent = won ? 'You win! 🎉' : 'You lose! The word was ' + secretWord;
    } else {
      messageEl.textContent = 'Wrong guesses: ' + wrongGuesses + ' / ' + MAX_WRONG;
    }
  }

  function drawHangman() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#f5f5f5';
    ctx.lineWidth = 4;
    ctx.lineCap = 'square';

    // Gallows base
    ctx.beginPath();
    ctx.moveTo(20, 180);
    ctx.lineTo(120, 180);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(70, 180);
    ctx.lineTo(70, 20);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(70, 20);
    ctx.lineTo(150, 20);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(150, 20);
    ctx.lineTo(150, 40);
    ctx.stroke();

    // Head
    if (wrongGuesses >= 1) {
      ctx.beginPath();
      ctx.arc(150, 55, 15, 0, Math.PI * 2);
      ctx.stroke();
    }
    // Body
    if (wrongGuesses >= 2) {
      ctx.beginPath();
      ctx.moveTo(150, 70);
      ctx.lineTo(150, 120);
      ctx.stroke();
    }
    // Left arm
    if (wrongGuesses >= 3) {
      ctx.beginPath();
      ctx.moveTo(150, 80);
      ctx.lineTo(125, 100);
      ctx.stroke();
    }
    // Right arm
    if (wrongGuesses >= 4) {
      ctx.beginPath();
      ctx.moveTo(150, 80);
      ctx.lineTo(175, 100);
      ctx.stroke();
    }
    // Left leg
    if (wrongGuesses >= 5) {
      ctx.beginPath();
      ctx.moveTo(150, 120);
      ctx.lineTo(125, 150);
      ctx.stroke();
    }
    // Right leg
    if (wrongGuesses >= 6) {
      ctx.beginPath();
      ctx.moveTo(150, 120);
      ctx.lineTo(175, 150);
      ctx.stroke();
    }
  }

  function updateButtons() {
    const buttons = letterButtons.querySelectorAll('button');
    buttons.forEach(function(btn) {
      const letter = btn.dataset.letter;
      btn.disabled = guessedLetters.has(letter) || gameOver;
    });
  }

  function checkGameState() {
    const won = secretWord.split('').every(function(ch) { return guessedLetters.has(ch); });
    if (won) {
      gameOver = true;
    } else if (wrongGuesses >= MAX_WRONG) {
      gameOver = true;
    }
    if (gameOver) {
      renderMessage();
      updateButtons();
    }
  }

  function handleGuess(letter) {
    if (gameOver || guessedLetters.has(letter)) return;
    guessedLetters.add(letter);
    if (secretWord.indexOf(letter) === -1) {
      wrongGuesses++;
      drawHangman();
    }
    renderWord();
    renderMessage();
    updateButtons();
    checkGameState();
  }

  function createLetterButtons() {
    letterButtons.innerHTML = '';
    for (let i = 65; i <= 90; i++) {
      const letter = String.fromCharCode(i);
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = letter;
      btn.dataset.letter = letter;
      btn.setAttribute('aria-label', 'Guess letter ' + letter);
      btn.addEventListener('click', function() {
        handleGuess(letter);
      });
      letterButtons.appendChild(btn);
    }
  }

  function resetGame() {
    secretWord = pickWord();
    guessedLetters = new Set();
    wrongGuesses = 0;
    gameOver = false;
    messageEl.textContent = '';
    createLetterButtons();
    renderWord();
    renderMessage();
    drawHangman();
    updateButtons();
    newGameBtn.focus();
  }

  newGameBtn.addEventListener('click', resetGame);

  // Keyboard support for letter guessing
  document.addEventListener('keydown', function(e) {
    if (gameOver) return;
    const key = e.key.toUpperCase();
    if (key.length === 1 && key >= 'A' && key <= 'Z') {
      const btn = letterButtons.querySelector('button[data-letter="' + key + '"]');
      if (btn && !btn.disabled) {
        handleGuess(key);
      }
    }
  });

  // Initialize
  resetGame();
})();
